CREATE TYPE "RoleName" AS ENUM ('USER','MODERATOR','ADMIN');
CREATE TYPE "ListingStatus" AS ENUM ('ACTIVE','HIDDEN','EXCHANGED');
CREATE TYPE "ItemCondition" AS ENUM ('NEW','LIKE_NEW','GOOD','FAIR');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"name" TEXT NOT NULL,"bio" TEXT,"isBlocked" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Role" ("id" TEXT PRIMARY KEY,"name" "RoleName" NOT NULL UNIQUE);
CREATE TABLE "UserRole" ("userId" TEXT NOT NULL,"roleId" TEXT NOT NULL,PRIMARY KEY ("userId","roleId"),FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE,FOREIGN KEY ("roleId") REFERENCES "Role"("id") ON DELETE CASCADE);
CREATE TABLE "Category" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL UNIQUE);
CREATE TABLE "Listing" ("id" TEXT PRIMARY KEY,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"condition" "ItemCondition" NOT NULL DEFAULT 'GOOD',"status" "ListingStatus" NOT NULL DEFAULT 'ACTIVE',"exchangeFor" TEXT,"city" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"ownerId" TEXT NOT NULL,"categoryId" TEXT NOT NULL,FOREIGN KEY ("ownerId") REFERENCES "User"("id"),FOREIGN KEY ("categoryId") REFERENCES "Category"("id"));
CREATE TABLE "ListingImage" ("id" TEXT PRIMARY KEY,"url" TEXT NOT NULL,"listingId" TEXT NOT NULL,FOREIGN KEY ("listingId") REFERENCES "Listing"("id") ON DELETE CASCADE);
CREATE TABLE "Favorite" ("userId" TEXT NOT NULL,"listingId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY ("userId","listingId"),FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE,FOREIGN KEY ("listingId") REFERENCES "Listing"("id") ON DELETE CASCADE);
CREATE TABLE "Conversation" ("id" TEXT PRIMARY KEY,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ConversationMember" ("conversationId" TEXT NOT NULL,"userId" TEXT NOT NULL,PRIMARY KEY ("conversationId","userId"),FOREIGN KEY ("conversationId") REFERENCES "Conversation"("id") ON DELETE CASCADE,FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "Message" ("id" TEXT PRIMARY KEY,"body" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"conversationId" TEXT NOT NULL,"senderId" TEXT NOT NULL,FOREIGN KEY ("conversationId") REFERENCES "Conversation"("id") ON DELETE CASCADE,FOREIGN KEY ("senderId") REFERENCES "User"("id"));
CREATE TABLE "Report" ("id" TEXT PRIMARY KEY,"reason" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'OPEN',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"reporterId" TEXT NOT NULL,"listingId" TEXT NOT NULL,FOREIGN KEY ("reporterId") REFERENCES "User"("id"),FOREIGN KEY ("listingId") REFERENCES "Listing"("id") ON DELETE CASCADE);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY,"action" TEXT NOT NULL,"details" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"userId" TEXT,FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL);
CREATE TABLE "RefreshToken" ("id" TEXT PRIMARY KEY,"tokenHash" TEXT NOT NULL UNIQUE,"expiresAt" TIMESTAMP(3) NOT NULL,"userId" TEXT NOT NULL,FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE INDEX "Listing_title_idx" ON "Listing"("title");
CREATE INDEX "Listing_categoryId_status_idx" ON "Listing"("categoryId","status");
CREATE INDEX "Listing_createdAt_idx" ON "Listing"("createdAt");
CREATE INDEX "Message_conversationId_createdAt_idx" ON "Message"("conversationId","createdAt");
CREATE INDEX "AuditLog_createdAt_idx" ON "AuditLog"("createdAt");
